-- Notion 검토 사항 DB 스키마 (notion-create-database의 schema 인자에 그대로 사용)
-- 규칙 선택지('규칙1 …')는 프로젝트의 story-service 필수 규칙 이름으로 바꾸고, project.json notion.rule_options와 맞춘다.
CREATE TABLE ("검토 사항" TITLE, "항목 ID" RICH_TEXT COMMENT '실행 간 유지되는 ID, 예: CHK-S2-014 (하네스)', "판정" SELECT('FAIL':red, 'NEEDS_REVIEW':yellow, 'INSUFFICIENT_INFO':gray) COMMENT '하네스', "단계" SELECT('S2 요구사항·흐름':blue, 'S3 컴포넌트':purple, 'S4 영향 분석':orange) COMMENT '하네스', "플랫폼" MULTI_SELECT('사용자앱':green, '관리자웹':brown) COMMENT '하네스', "화면" RICH_TEXT COMMENT '화면 ID · 프레임 이름 · 노드 ID (하네스)', "영향 화면" RICH_TEXT COMMENT 'S4 결과 (하네스)', "필수 규칙" SELECT('규칙1':red, '규칙2':red, '해당 없음':default) COMMENT '하네스', "사유" RICH_TEXT COMMENT '하네스', "근거" RICH_TEXT COMMENT 'source_id + 위치 (하네스)', "후속 조치" RICH_TEXT COMMENT '하네스', "수정 완료" CHECKBOX COMMENT '사용자 입력 — 하네스는 변경하지 않음', "컨펌 완료" CHECKBOX COMMENT '사용자 입력 — 하네스는 변경하지 않음', "결정 메모" RICH_TEXT COMMENT '사용자 입력 — 컨펌 완료 시 필수', "재검증 결과" SELECT('미실행':gray, 'PASS':green, '여전히 FAIL':red) COMMENT '하네스', "최근 실행" RICH_TEXT COMMENT 'run-id (하네스)')
